actions.script:
duplicate = false
result = null
const userId = ec.user.userId
if (!userId) { ec.message.addError('No user'); return }
if (!/^[A-Za-z0-9_.:-]{1,64}$/.test(String(clientRef))) { ec.message.addError(ec.l10n.localize('A clientRef is up to 64 letters, digits and _ . : -')); return }
const row = ec.entity.find('moqui.basic.client.ClientRequestRef').condition({userId: userId, serviceName: serviceName, clientRef: String(clientRef)})
        .disableAuthz().one()
if (row) {
    duplicate = true
    try { result = row.resultJson ? JSON.parse(row.resultJson) : {} } catch (err) { result = {} }
    return
}
const claim = ec.entity.makeValue('moqui.basic.client.ClientRequestRef')
claim.setFields({userId: userId, serviceName: serviceName, clientRef: String(clientRef), createdDate: ec.user.nowTimestamp}, true, null, null)
claim.create()

const userId = ec.user.userId
if (!userId) { ec.message.addError('No user'); return }
let json = null
try {
    json = JSON.stringify(result || {}, function (key, value) {
        const raw = this[key]
        if (raw instanceof Date) return raw.getTime()
        return typeof value === 'bigint' ? Number(value) : value
    })
} catch (err) {
    ec.logger.warn(`The answer of ${serviceName} for clientRef ${clientRef} is not kept: ${err && err.message ? err.message : err}`)
    json = '{}'
}
if (json.length > 262144) json = '{}'
const pk = {userId: userId, serviceName: serviceName, clientRef: String(clientRef)}
const row = ec.entity.find('moqui.basic.client.ClientRequestRef').condition(pk).disableAuthz().one()
if (row) { row.set('resultJson', json); row.update() }
else {
    const created = ec.entity.makeValue('moqui.basic.client.ClientRequestRef')
    created.setFields(Object.assign({resultJson: json, createdDate: ec.user.nowTimestamp}, pk), true, null, null)
    created.create()
}

duplicate = false
result = {}
const ref = clientRef != null && clientRef !== '' ? String(clientRef) : null
if (ref) {
    const claim = ec.service.sync().name('org.moqui.edge.ClientSyncServices.claim#ClientRequest').parameters({clientRef: ref, serviceName: serviceName}).call()
    if (ec.message.hasError()) return
    if (claim.duplicate) { duplicate = true; result = claim.result || {}; return }
}
result = ec.service.sync().name(serviceName).parameters(parameters || {}).call() || {}
if (ec.message.hasError()) return
if (ref) ec.service.sync().name('org.moqui.edge.ClientSyncServices.store#ClientRequest').parameters({clientRef: ref, serviceName: serviceName,
    result: result}).call()

const UPLOAD = 'moqui.basic.client.ClientUpload'
const L = (text) => ec.l10n.localize(text)
accepted = false
complete = false
received = 0
const userId = ec.user.userId
if (!userId) { ec.message.addError('No user'); return }
uploadId = String(uploadId)
if (!/^[A-Za-z0-9_.:-]{1,64}$/.test(uploadId)) { ec.message.addError(L('An uploadId is up to 64 letters, digits and _ . : -')); return }
const size = Number(total)
if (!(size > 0)) { ec.message.addError(L('An upload needs its total size')); return }
const limit = Math.min(Number(maxBytes || 26214400), 26214400)
if (size > limit) { ec.message.addError(ec.resource.expand('${name} is over 25 MB', '', {name: fileName || uploadId})); return }
const at = Number(offset)
const part = Array.isArray(chunk) ? chunk[0] : chunk
let row = ec.entity.find(UPLOAD).condition({userId: userId, uploadId: uploadId}).forUpdate(true).disableAuthz().one()
if (row && Number(row.totalSize) !== size) { ec.message.addError(ec.resource.expand('The upload ${uploadId} is of another file', '', {uploadId: uploadId})); return }
if (row && row.completedDate != null) { received = Number(row.receivedSize); complete = true; return }
received = row ? Number(row.receivedSize || 0) : 0
// only the next bytes: a chunk sent again, or one past a gap, is answered with what is held
if (at !== received) return
if (part == null || typeof part !== 'object') { ec.message.addError(L('No chunk uploaded')); return }
const partSize = Number(typeof part.getSize === 'function' ? part.getSize() : (part.size || 0))
if (!(partSize > 0)) { ec.message.addError(L('The chunk is empty')); return }
if (at + partSize > size) { ec.message.addError(L('The chunk goes past the total size')); return }
const property = (name, fallback) => { const value = Number(System.getProperty(name)); return value > 0 ? value : fallback }
const minChunk = property('client_upload_min_chunk_bytes', 262144)
if (at + partSize < size && partSize < minChunk) {
    ec.message.addError(ec.resource.expand('A chunk other than the last is at least ${bytes} bytes', '', {bytes: minChunk})); return }
const now = ec.user.nowTimestamp
if (!row) {
    // what the user has open: a new upload past the limits waits for one to finish or expire
    const open = Array.from(ec.entity.find(UPLOAD).condition('userId', userId).condition(ec.entity.conditionFactory.makeCondition('completedDate', 'is-null', null))
            .selectField('totalSize').disableAuthz().list())
    const maxCount = property('client_upload_max_count', 20)
    const maxBytesOpen = property('client_upload_max_mb', 100) * 1048576
    if (open.length >= maxCount) {
        ec.message.addError(ec.resource.expand('At most ${count} uploads at once: finish one first', '', {count: maxCount})); return }
    if (open.reduce((sum, item) => sum + Number(item.totalSize || 0), 0) + size > maxBytesOpen) {
        ec.message.addError(ec.resource.expand('At most ${mb} MB of uploads at once: finish one first', '', {mb: maxBytesOpen / 1048576})); return }
    const token = Math.random().toString(36).substring(2, 10) + Date.now().toString(36)
    row = ec.entity.makeValue(UPLOAD)
    row.setFields({userId: userId, uploadId: uploadId, fileName: String(fileName || 'file').split(/[\\/]/).pop().substring(0, 200) || 'file',
        contentType: contentType || null, totalSize: size, receivedSize: 0, chunkCount: 0,
        storeLocation: `dbresource://upload/${userId}/${token}`, createdDate: now}, true, null, null)
    row.create()
}
const chunkName = (start) => String(start).padStart(10, '0')
const store = String(row.storeLocation)
if (typeof part.write === 'function') part.write(`${store}/${chunkName(at)}`)
else {
    const stream = part.getInputStream()
    try { ec.resource.getLocationReference(`${store}/${chunkName(at)}`).putStream(stream) } finally { if (stream && stream.close) stream.close() }
}
received = at + partSize
accepted = true
row.set('receivedSize', received)
row.set('chunkCount', Number(row.chunkCount || 0) + 1)
row.set('lastChunkDate', now)
if (received === size) {
    // every byte is here: the chunks become the file, in their order, each read into the file's one buffer
    const file = new Uint8Array(size)
    const starts = []
    for (let start = 0; start < size;) {
        let bytes = ec.resource.getLocationReference(`${store}/${chunkName(start)}`).openStream()?.readAllBytes()
        if (!bytes || !bytes.length || start + bytes.length > size) {
            ec.message.addError(ec.resource.expand('The chunk at ${start} of upload ${uploadId} is missing', '', {start: start, uploadId: uploadId})); return }
        file.set(bytes, start)
        starts.push(start)
        start += bytes.length
        bytes = null
    }
    ec.resource.getLocationReference(`${store}/file`).putBytes(file)
    for (const start of starts) {
        try { ec.resource.getLocationReference(`${store}/${chunkName(start)}`).delete() }
        catch (err) { ec.logger.warn(`Could not remove chunk ${start} of upload ${uploadId}: ${err && err.message ? err.message : err}`) }
    }
    row.set('completedDate', now)
    complete = true
}
row.update()

const row = ec.user.userId ? ec.entity.find('moqui.basic.client.ClientUpload').condition({userId: ec.user.userId, uploadId: String(uploadId)})
        .disableAuthz().one() : null
if (!row) { ec.message.addError(ec.resource.expand('Upload ${uploadId} not found', '', {uploadId: uploadId})); return }
if (row.completedDate == null) { ec.message.addError(ec.resource.expand('Upload ${uploadId} is not complete', '', {uploadId: uploadId})); return }
location = `${row.storeLocation}/file`
fileName = row.fileName || 'file'
contentType = row.contentType || 'application/octet-stream'
fileSize = Number(row.totalSize || 0)

removedCount = 0
const keep = Math.max(1, Number(hours || System.getProperty('client_upload_expire_hours') || 24))
const before = Number(ec.user.nowTimestamp) - keep * 3600000
const cf = ec.entity.conditionFactory
// read through the find's iterator, so a long backlog is not held whole; each removal runs in a
// transaction of its own beside the cursor
const rows = ec.entity.find('moqui.basic.client.ClientUpload').condition(cf.makeCondition([
    cf.makeCondition('lastChunkDate', 'less', String(before)),
    cf.makeCondition([cf.makeCondition('lastChunkDate', 'is-null', null), cf.makeCondition('createdDate', 'less', String(before))], 'and')], 'or'))
        .selectField('userId').selectField('uploadId').disableAuthz().iterator()
const users = new Set()
try { for (const row of rows) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.edge.ClientSyncServices.remove#ClientUpload').parameters({userId: row.userId, uploadId: row.uploadId})
                .requireNewTransaction(true).disableAuthz().call()
        if (ec.message.hasError()) ec.logger.error(`Could not remove upload ${row.uploadId} of user ${row.userId}: ${ec.message.errorsString}`)
        else { removedCount++; users.add(row.userId) }
    } catch (err) {
        ec.logger.error(`Could not remove upload ${row.uploadId} of user ${row.userId}: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
} } finally { rows.close() }
for (const userId of users) {
    try {
        const folder = ec.resource.getLocationReference(`dbresource://upload/${userId}`)
        if (folder.getExists() && !Array.from(folder.getDirectoryEntries() || []).length) folder.delete()
    } catch (err) {
        ec.logger.warn(`Could not remove the upload folder of user ${userId}: ${err && err.message ? err.message : err}`)
    }
}

if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('remove#ClientUpload is internal'); return }
const row = ec.entity.find('moqui.basic.client.ClientUpload').condition({userId: userId, uploadId: uploadId}).forUpdate(true).one()
if (!row) return
const store = row.storeLocation ? String(row.storeLocation) : null
if (store && store.startsWith('dbresource://upload/')) {
    const directory = ec.resource.getLocationReference(store)
    if (directory.getExists()) {
        for (const child of Array.from(directory.getDirectoryEntries() || [])) child.delete()
        directory.delete()
    }
}
row.delete()
